package com.yeyamo_mobile.api.recommendation_service.infrastructure.cache;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Duration;import java.util.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.recommendation_service.application.*;import com.yeyamo_mobile.api.recommendation_service.application.port.RecommendationCachePort;import com.yeyamo_mobile.api.recommendation_service.domain.RecommendationContext;
@Component public class RedisRecommendationCacheAdapter implements RecommendationCachePort{private static final Logger log=LoggerFactory.getLogger(RedisRecommendationCacheAdapter.class);private static final String VERSION="recommendation:cache:version";private final StringRedisTemplate redis;private final ObjectMapper mapper;private final Duration ttl;public RedisRecommendationCacheAdapter(StringRedisTemplate r,ObjectMapper m,@Value("${recommendation.cache.ttl-seconds:120}")long seconds){redis=r;mapper=m;ttl=Duration.ofSeconds(Math.max(1,seconds));}public Optional<RecommendationPage>get(String u,RecommendationContext c,int p,int s){try{String value=redis.opsForValue().get(key(u,c,p,s));return value==null?Optional.empty():Optional.of(mapper.readValue(value,RecommendationPage.class));}catch(Exception e){log.debug("Recommendation cache read unavailable: {}",e.getMessage());return Optional.empty();}}public void put(String u,RecommendationContext c,int p,int s,RecommendationPage result){try{redis.opsForValue().set(key(u,c,p,s),mapper.writeValueAsString(result),ttl);}catch(Exception e){log.debug("Recommendation cache write unavailable: {}",e.getMessage());}}public void invalidate(){try{redis.opsForValue().increment(VERSION);}catch(RuntimeException e){log.debug("Recommendation cache invalidation unavailable: {}",e.getMessage());}}private String key(String u,RecommendationContext c,int p,int s)throws Exception{String v=redis.opsForValue().get(VERSION);if(v==null)v="0";String raw=u+"|"+c+"|"+p+"|"+s;return"recommendation:v"+v+":"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}}
